letion, Column_25, MaterialBudget, MaterialBudgetMods, MaterialModifiedBudget, MaterialProjectedCostoverbudgettoComplete, MaterialEstimateatcompletion, Column_31, EngineeringBudget, EngineeringBudgetMods, EngineeringModifiedBudget, EngineeringProjectedCostoverbudgettoComplete, EngineeringEstimateatcompletion, EstimateatCompletionAddlOHCosted, Column_37, TotalDirectCostModifiedBudget, TotalDirectCostEstToComplete, Column_40, CurrentMonthBasedonModifiedBudget, CurrentMonthBasedonEsttoComplete, FrameSizeOEM, Column_44, PMTotalDirCostEstToComplete, Diff, Comment, Column_48, Column_49 FROM Budget.BudgetsandAssumptions;
CREATE VIEW MaterialLaborBudget ( JobID string(50) OPTIONS(SEARCHABLE 'UNSEARCHABLE'), Fringe string(50) OPTIONS(SEARCHABLE 'UNSEARCHABLE'), Material string(50) OPTIONS(SEARCHABLE 'UNSEARCHABLE'), Engineering string(50) OPTIONS(SEARCHABLE 'UNSEARCHABLE'), DirectLabor string(50) OPTIONS(SEARCHABLE 'UNSEARCHABLE') ) OPTIONS(NAMEINSOURCE 'MgtRptg', UPDATABLE 'TRUE') AS SELECT Budget.MgtRptg.column_1 AS JobID, Budget.MgtRptg.TotalBudgetedCostsLaborFringeBurden AS Fringe, Budget.MgtRptg.TotalBudgetedCostsMaterialCost AS Material, Budget.MgtRptg.TotalBudgetedCostsDirectEngineering AS Engineering, Budget.MgtRptg.TotalBudgetedCostsTotalDirectCosts AS DirectLabor FROM Budget.MgtRptg;
CREATE VIEW BudgetSummaryLevel2 ( JobID string(50) OPTIONS(SEARCHABLE 'UNSEARCHABLE'), Material double OPTIONS(SEARCHABLE 'UNSEARCHABLE'), DirectLabor double OPTIONS(SEARCHABLE 'UNSEARCHABLE'), Engineering double OPTIONS(SEARCHABLE 'UNSEARCHABLE'), Fringe double OPTIONS(SEARCHABLE 'UNSEARCHABLE') ) OPTIONS(NAMEINSOURCE 'MgtRptg', UPDATABLE 'TRUE') AS SELECT LATBudgetViewModel.MaterialLaborBudget.JobID, SUM(parseFloat(LATBudgetViewModel.MaterialLaborBudget.Material, '0.00;-0.00')) AS Material, SUM(parseFloat(LATBudgetViewModel.MaterialLaborBudget.DirectLabor, '0.00;-0.00')) AS DirectLabor, SUM(parseFloat(LATBudgetViewModel.MaterialLaborBudget.Engineering, '0.00;-0.00')) AS Engineering, SUM(parseFloat(LATBudgetViewModel.MaterialLaborBudget.Fringe, '0.00;-0.00')) AS Fringe FROM LATBudgetViewModel.MaterialLaborBudget GROUP BY LATBudgetViewModel.MaterialLaborBudget.JobID;

